(async()=>{const L=[];try{const RIP=new Set(["G_ADDR6", "G_ADDR7", "G_CAB", "G_CD_TALLY", "G_CHANCUT_EVENT", "G_CHAN_CONTROL", "G_CPEB", "G_CUT_A", "G_EQ_CONTROL", "G_EQ_EVENT", "G_FSB", "G_GROUP_TALLY", "G_INS_CONTROL", "G_INS_EVENT", "G_LC_CONTROL", "G_MASTER_MIC", "G_MDB", "G_MIC_COUGH", "G_MIC_TALLY", "G_MONCUT_EVENT", "G_MSCB", "G_ODB", "G_OVERLOAD", "G_OVL_MASTER", "G_SFBB", "G_SHB", "G_SRB", "G_TIB", "G_TIMB", "G_TIMT", "LDRV_1", "LDRV_10", "LDRV_11", "LDRV_13", "LDRV_14", "LDRV_15", "LDRV_17", "LDRV_18", "LDRV_19", "LDRV_2", "LDRV_21", "LDRV_22", "LDRV_23", "LDRV_25", "LDRV_26", "LDRV_27", "LDRV_29", "LDRV_3", "LDRV_30", "LDRV_31", "LDRV_33", "LDRV_34", "LDRV_35", "LDRV_37", "LDRV_38", "LDRV_39", "LDRV_5", "LDRV_6", "LDRV_7", "LDRV_9", "L_MISO", "L_MISO_OC", "P12", "P17"]);const cs=await eda.pcb_PrimitiveComponent.getAll();for(const c of cs){const d=c.getState_Designator();if(d==='R194'){await eda.pcb_PrimitiveComponent.modify(c.getState_PrimitiveId(),{x:9625,y:-7500,rotation:90});L.push('R194 placed')}if(d==='D20'){await eda.pcb_PrimitiveComponent.modify(c.getState_PrimitiveId(),{x:9875,y:-7300,rotation:0});L.push('D20 placed')}}const LS=(await eda.pcb_PrimitiveLine.getAll()).filter(l=>RIP.has(l.net));for(let i=0;i<LS.length;i+=500)await eda.pcb_PrimitiveLine.delete(LS.slice(i,i+500).map(l=>l.primitiveId));L.push('lines-'+LS.length);const VS=(await eda.pcb_PrimitiveVia.getAll()).filter(v=>RIP.has(v.net));if(VS.length)await eda.pcb_PrimitiveVia.delete(VS.map(v=>v.primitiveId));L.push('vias-'+VS.length);for(const d of ['R194','D20']){const c=(await eda.pcb_PrimitiveComponent.getAll()).find(x=>x.getState_Designator()===d);const b=await eda.pcb_Primitive.getPrimitivesBBox([c.getState_PrimitiveId()]);L.push(d+' bbox '+[b.minX,b.minY,b.maxX,b.maxY].map(Math.round).join(','))}}catch(e){L.push('ERR '+e)}const f=new File([JSON.stringify(L)],'vrb_rip.json',{type:'application/json'});await eda.sys_FileSystem.saveFile(f,'vrb_rip.json');})();